import unicodedata


def slugify(s):
    # Transliterate Unicode characters to ASCII (e.g. õ -> o)
    s = unicodedata.normalize('NFKD', s)
    s = s.encode('ascii', 'ignore').decode('ascii')
    s = s.lower()

    # Replace every non-alphanumeric character with a single dash,
    # collapsing runs and stripping leading/trailing dashes.
    slug = []
    for ch in s:
        if ch.isalnum():
            slug.append(ch)
        elif not slug or slug[-1] != '-':
            slug.append('-')
    return ''.join(slug).strip('-')

import unicodedata


def slugify(s):
    s = s.lower()
    # Strip accents (e.g. õ -> o)
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(c for c in s if not unicodedata.combining(c))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif ch == ' ':
            out.append('-')
    # Collapse consecutive dashes and strip leading/trailing ones
    s = ''.join(out)
    while '--' in s:
        s = s.replace('--', '-')
    return s.strip('-')

