import unicodedata


def slugify(s):
    s = s.lower()
    out = []
    for ch in s:
        decomposed = unicodedata.normalize('NFD', ch)
        for c in decomposed:
            if unicodedata.category(c).startswith('M'):
                continue
            if c.isalnum():
                out.append(c)
            else:
                out.append('-')
    return '-'.join(filter(None, ''.join(out).split('-')))
